+        assert!(!mill_post_rotary(Kind::Mill, false, &p, &bare), "a mill answers by mill_order already");
+        assert!(newly_judged_on(Kind::MillTurn, &p) && newly_judged_on(Kind::Lathe, &p) && !newly_judged_on(Kind::Mill, &p));
+    }
+}

